206|<script>
207|(function () {
208|  var id = {{ view.id | tojson }};
209|  document.addEventListener("click", function (event) {
210|    var btn = null;
211|    if (event.target && event.target.closest) {
212|      btn = event.target.closest("button[data-url]");
213|    }
214|    if (!btn) {
215|      return;
216|    }
217|    var url = btn.getAttribute("data-url");
218|    var method = btn.getAttribute("data-method") || "POST";
219|    var body = {};
220|    var from = btn.getAttribute("data-body-from");
221|    var fields = btn.getAttribute("data-field");
222|    if (from && fields) {
223|      var ids = from.split(",");
224|      var keys = fields.split(",");
225|      for (var i = 0; i < ids.length; i++) {
226|        var inputId = ids[i].trim();
227|        var key = (keys[i] || "").trim();
228|        if (!inputId || !key) {
229|          continue;
230|        }
231|        var input = document.getElementById(inputId);
232|        if (!input) {
233|          continue;
234|        }
235|        if (input.type === "number") {
236|          var n = parseInt(input.value || "0", 10);
237|          body[key] = isNaN(n) ? 0 : n;
238|        } else {
239|          body[key] = input.value;
240|        }
241|      }
242|    }
243|    fetch(url, {method: method, headers: {"Content-Type": "application/json"}, body: JSON.stringify(body)}).then(function (resp) {
244|      if (resp.ok) {
245|        window.location.reload();
246|      } else {
247|        resp.json().then(function (data) {
248|          var err = document.getElementById("action-error");
249|          var msg = (data && data.error) ? data.error : ("request failed: " + resp.status);
250|          if (err) {
251|            err.textContent = msg;
252|            err.style.display = "block";
253|          }
254|        }).catch(function () {
255|          var err2 = document.getElementById("action-error");
256|          if (err2) {
257|            err2.textContent = "request failed: " + resp.status;
258|            err2.style.display = "block";
259|          }
260|        });
261|      }
262|    }).catch(function (err3) {
263|      var box = document.getElementById("action-error");
264|      if (box) {
265|        box.textContent = String(err3 && err3.message ? err3.message : err3);
266|        box.style.display = "block";
267|      }
268|    });
269|  });
270|  document.querySelectorAll("details").forEach(function (box) {
271|    var loaded = false;
272|    box.addEventListener("toggle", function () {
273|      if (!box.open || loaded) return;
274|      var target = box.querySelector("[data-turn-input]");
275|      if (!target) return;
276|      loaded = true;
277|      var n = target.dataset.turnInput;
278|      fetch("/api/incidents/" + id + "/turns/" + n + "/input").then(function (r) { return r.json(); }).then(function (data) {
279|        target.innerHTML = "";
280|        data.forEach(function (item) {
281|          var wrap = document.createElement("div");
282|          if (item.role === "developer") {
283|            var inner = document.createElement("details");
284|            var sum = document.createElement("summary");
285|            sum.textContent = "developer prompt";
286|            inner.appendChild(sum);
287|            var pre = document.createElement("pre");
288|            pre.textContent = JSON.stringify(item, null, 2);
289|            inner.appendChild(pre);
290|            wrap.appendChild(inner);
291|          } else {
292|            var blk = document.createElement("pre");
293|            blk.textContent = JSON.stringify(item, null, 2);
294|            wrap.appendChild(blk);
295|          }
296|          target.appendChild(wrap);
297|        });
298|      });
299|    });
300|  });
301|})();
302|</script>
303|<script>
304|(function () {
305|  var known = null;
306|  function poll() {
307|    fetch("/api/version").then(function (r) { return r.json(); }).then(function (data) {
308|      if (known === null) { known = data.version; return; }
309|      if (data.version !== known) {
310|        if (document.querySelector("details[open]")) {
311|          document.getElementById("stale").style.display = "block";
312|          known = data.version;
313|        } else { window.location.reload(); }
314|      }
315|    }).catch(function () {});
316|  }
317|  setInterval(poll, 2000);
318|})();
319|</script>
320|</body>
321|</html>

