<body>
<header class="topbar">
<div class="topbar-main">
<a class="brand" href="/">Fleet SRE</a>
{% if admin %}
<div class="segments" role="group" aria-label="Act">
{% for name in demo.acts %}
<button type="button" class="seg{% if name == demo.act %} seg-current{% endif %}" title="{{ demo.act_titles[name] }}" data-url="/api/demo/act" data-method="POST" data-act="{{ name }}"{% if name == demo.act %} aria-current="true"{% endif %}>{{ name }}</button>
{% endfor %}
</div>
{% else %}
<p class="act-label">Act {{ demo.act }} &mdash; {{ demo.title }}</p>
{% endif %}
<div class="topbar-right">
<span class="clock" title="Sim time">{{ demo.now[11:19] }}</span>
{% if demo.live %}<span class="pill">Live: {{ demo.model }}</span>{% else %}<span class="pill">Scripted replay</span>{% endif %}
{% if admin %}<span class="pill pill-admin">Admin</span>{% endif %}
{% if demo.held %}<span class="pill pill-held">Clock held</span>{% endif %}
</div>
</div>
<div class="topbar-meta">
{% if admin_error %}<span class="meta-notice">admin token not accepted</span>{% endif %}
<span>Model calls: {{ demo.model_calls }}{% if demo.last_model_call_at %} (last {{ demo.last_model_call_at[11:19] }}){% endif %}</span>
<span>Active faults:{% if demo.active_faults %} {% for f in demo.active_faults %}{{ f.id }} {{ f.type }} {{ f.environment }}{% if not loop.last %}; {% endif %}{% endfor %}{% else %} none{% endif %}</span>
{% if demo.exhausted %}<span class="meta-notice">script ended: switch act to restart</span>{% endif %}
<span id="stale">updated: reload</span>
</div>
</header>
<main>
{% block content %}{% endblock %}
</main>
