    var err = document.getElementById("action-error");
    if (err) {
      err.textContent = message;
      err.style.display = "block";
    }
  }
  document.addEventListener("click", function (event) {
    var btn = null;
    if (event.target && event.target.closest) {
      btn = event.target.closest("button[data-url]");
    }
    if (!btn || btn.disabled) {
      return;
    }
    var url = btn.getAttribute("data-url");
    var method = btn.getAttribute("data-method") || "POST";
    var body = {};
    if (btn.hasAttribute("data-act")) {
      body = {act: btn.getAttribute("data-act")};
    } else {
      var from = btn.getAttribute("data-body-from");
      var fields = btn.getAttribute("data-field");
      if (from && fields) {
        var ids = from.split(",");
        var keys = fields.split(",");
        for (var i = 0; i < ids.length; i++) {
          var inputId = ids[i].trim();
          var key = (keys[i] || "").trim();
          if (!inputId || !key) {
            continue;
          }
          var input = document.getElementById(inputId);
          if (!input) {
            continue;
          }
          if (input.type === "number") {
            var n = parseInt(input.value || "0", 10);
            body[key] = isNaN(n) ? 0 : n;
          } else {
            body[key] = input.value;
          }
        }
      }
    }
    var original = btn.textContent;
    btn.disabled = true;
    btn.textContent = "Sent\u2026";
    function restore() {
      btn.disabled = false;
      btn.textContent = original;
    }
    fetch(url, {method: method, headers: {"Content-Type": "application/json"}, body: JSON.stringify(body)}).then(function (resp) {
      if (resp.ok) {
        window.location.reload();
      } else {
        resp.json().then(function (data) {
          var msg = (data && data.error) ? data.error : ("request failed: " + resp.status);
          restore();
          showError(msg);
        }).catch(function () {
          restore();
          showError("request failed: " + resp.status);
        });
      }
    }).catch(function (err) {
      restore();
      showError(String(err && err.message ? err.message : err));
    });
  });
})();
</script>
<script>
(function () {
  var known = null;
  function poll() {
    fetch("/api/version").then(function (r) { return r.json(); }).then(function (data) {
      if (known === null) { known = data.version; return; }
      if (data.version !== known) {
        if (document.querySelector("details[open]")) {
          document.getElementById("stale").style.display = "block";
          known = data.version;
        } else { window.location.reload(); }
      }
    }).catch(function () {});
  }
  setInterval(poll, 2000);
})();
</script>
{% block scripts %}{% endblock %}
</body>
</html>
","path":"fleetsre/web/templates/base.html"}

