{"content":"{% extends "base.html" %}
{% block title %}{{ demo.title }} &mdash; Fleet SRE{% endblock %}
{% block content %}
{% if demo.title %}
<h1>{{ demo.title }}</h1>
{% else %}
<h1>{{ view.tripwires[0] }} on {{ view.deployment.split('/')[-1] }}</h1>
{% endif %}
<p class="inc-id"><code>{{ view.id }}</code></p>
<p class="inc-meta">Deployment: {{ view.deployment }} | State: {{ view.state }}{% if view.reason %} | Reason: {{ view.reason }}{% endif %}</p>
<p class="inc-meta">Tripwires: {{ view.tripwires | join(", ") }}</p>

<section class="banner state-{{ view.state | lower }}" aria-label="Next step">
<div class="banner-top">
<span class="state-chip">{{ view.state }}</span>
<span class="actor-chip actor-{{ view.next_step.actor }}">{{ view.next_step.actor }}</span>
</div>
{% if admin %}
<p class="next-text">{{ view.next_step.text }}</p>
{% else %}
<p class="next-text">{{ view.next_step.text | replace("(Mark rotated), ", "") | replace("(Mark rotated)", "") }}</p>
{% endif %}
{% if view.state == "NEEDS_INPUT" and view.handoff %}
<span class="pause-info">model calls since pause: {{ view.handoff.model_calls_since_pause }} (paused at {{ view.handoff.paused_at }})</span>
{% endif %}
{% if admin and view.next_step.actor == "you" %}
{% include "_controls.html" %}
{% endif %}
</section>

{% if admin and view.next_step.actor != "you" %}
{% include "_controls.html" %}
{% endif %}

<h2>Incident story</h2>
<ol class="timeline">
{% for entry in view.story %}
{% set next = view.story[loop.index0 + 1] if not loop.last else none %}
{% if entry.kind == "segment" and next is not none and next.at == entry.at and next.kind in ["proposal", "needs_input"] %}
{% else %}
<li class="tl-entry actor-{{ entry.actor }}">
<span class="tl-dot" aria-hidden="true"></span>
<div class="tl-meta">
<span class="actor-chip actor-{{ entry.actor }}">{{ entry.actor }}</span>
<time>{{ entry.at[11:19] }}</time>
<span class="t-rel">{{ entry.elapsed }}</span>
</div>
{% if entry.kind == "proposal" and entry.change is defined %}
<p class="tl-text">Proposed #{{ entry.change.seq }}{% if entry.change.category %}: {{ entry.change.category }}: {{ entry.change.summary }}{% endif %}</p>
<ul class="change">
{% for line in entry.change.lines %}
<li><code>{{ line }}</code></li>
{% endfor %}
</ul>
{% else %}
<p class="tl-text">{% if entry.kind == "needs_input" and "escalated" in entry.text and view.diagnosis %}<strong>{{ view.diagnosis.category }}: {{ view.diagnosis.summary }}</strong> &mdash; {% endif %}{{ entry.text }}</p>
{% endif %}
{% if entry.actor == "sre" %}
<details>
<summary>Hypotheses and evidence</summary>
<ul class="hyp-list">
{% for h in view.hypotheses %}
<li><strong>{{ h.id }}</strong>: {{ h.statement }}
<span class="confirm">Would confirm: {{ h.wouldConfirm }}{% if h.alternative %} (alternative){% endif %}</span>
<ul class="ev-list">
{% for e in view.evidence if e.hypothesis == h.id %}
<li><span class="stance stance-{{ e.stance }}">{{ e.stance }}</span> {{ e.id }} (turn {{ e.recordedAtTurn }}): {{ e.why }} &mdash; {{ e.source.kind }}{% if e.source.kind == "log" %} {{ e.source.insertId }} {{ e.source.severity }}{% else %} {{ e.source.tool }} {{ e.source.field }}={{ e.source.value }}{% endif %}</li>
{% endfor %}
</ul>
</li>
{% endfor %}
</ul>
</details>
{% endif %}
</li>
{% endif %}
{% endfor %}
</ol>

<h2>Proposal</h2>
{% if view.proposal %}
<div class="card">
<p><code>{{ view.proposal.method }}</code> <span class="res-short" title="{{ view.proposal.resource }}">{{ view.proposal.resource.split('/')[-1] }}</span></p>
<p class="proposal-meta">seq {{ view.proposal.seq }} &middot; <code>{{ view.proposal.hash }}</code></p>
{% if view.proposal.diff %}
<table class="diff">
<thead><tr><th>Field</th><th>Before</th><th>After</th></tr></thead>
<tbody>
{% for row in view.proposal.diff %}
<tr><td>{{ row.field }}</td><td>{{ row.before }}</td><td>{{ row.after }}</td></tr>
{% endfor %}
</tbody>
</table>
{% else %}
<p>{{ view.proposal.steps }}</p>
{% endif %}
</div>
{% else %}
<p>No proposal.</p>
{% endif %}

<h2>Verification</h2>
{% if view.verification %}
<div class="card compact">
<p><strong>{{ view.verification.tripwire }}</strong> <span class="pill state-{{ view.verification.current }}">{{ view.verification.current }}</span> {{ view.verification.outcome }}</p>
<p class="inc-meta">started {{ view.verification.started_at }} &middot; deadline {{ view.verification.deadline }}</p>
</div>
{% else %}
<p>No verification.</p>
{% endif %}

{% if view.postmortem %}
<h2>Postmortem</h2>
<div class="card compact">
<p>Outcome: {{ view.postmortem.outcome }}</p>
<p>Category: {{ view.postmortem.category }}</p>
<p>Root cause: {{ view.postmortem.root_cause }}</p>
</div>
{% endif %}

<details>
<summary>SRE turn by turn ({{ view.turns | length }} turns)</summary>
<p>Turns: {{ view.header.turns }}, model calls: {{ view.header.model_calls }}, read calls: {{ view.header.read_calls }}, cost: {% if demo.live %}{{ "$%.4f"|format(view.header.cost_usd) }}{% else %}n/a (scripted){% endif %}</p>
{% set resumed = view.timeline | selectattr("kind", "equalto", "resumed") | list %}
{% for card in view.turns %}
{% if card.segment > 1 and (loop.first or view.turns[loop.index0 - 1].segment != card.segment) %}
<div class="segment-divider">Segment {{ card.segment }} resumed (trigger: {{ resumed[card.segment - 2].detail.trigger }}) &mdash; {{ resumed[card.segment - 2].detail.message }}</div>
{% endif %}
<div class="turn-card {{ card.verdict }}">
<div class="turn-row">
<span class="turn-n">Turn {{ card.n }}</span>
<span class="turn-tool">{{ card.act.tool if card.act else "no tool call" }}</span>
<span class="turn-think">{{ card.think }}</span>
<span class="verdict verdict-{{ card.verdict }}">{{ card.verdict }}</span>
</div>
<details>
<summary>JSON</summary>
{% if card.act %}<pre>{{ card.act.args | tojson(indent=2) }}</pre>{% endif %}
{% if card.observe is not none %}<pre>{{ card.observe | tojson(indent=2) }}</pre>{% endif %}
</details>
<details>
<summary>Exact input</summary>
<div data-turn-input="{{ card.n }}">Loading exact input&hellip;</div>
</details>
</div>
{% endfor %}
</details>
{% endblock %}
{% block scripts %}
<script>
(function () {
  var id = {{ view.id | tojson }};
  document.querySelectorAll("details").forEach(function (box) {
    var loaded = false;
    box.addEventListener("toggle", function () {
      if (!box.open || loaded) return;
      var target = box.querySelector("[data-turn-input]");
      if (!target) return;
      loaded = true;
      var n = target.dataset.turnInput;
      fetch("/api/incidents/" + id + "/turns/" + n + "/input").then(function (r) { return r.json(); }).then(function (data) {
        target.innerHTML = "";
        data.forEach(function (item) {
          var wrap = document.createElement("div");
          if (item.role === "developer") {
            var inner = document.createElement("details");
            var sum = document.createElement("summary");
            sum.textContent = "developer prompt";
            inner.appendChild(sum);
            var pre = document.createElement("pre");
            pre.textContent = JSON.stringify(item, null, 2);
            inner.appendChild(pre);
            wrap.appendChild(inner);
          } else {
            var blk = document.createElement("pre");
            blk.textContent = JSON.stringify(item, null, 2);
            wrap.appendChild(blk);
          }
          target.appendChild(wrap);
        });
      });
    });
  });
})();
</script>
{% endblock %}
","path":"fleetsre/web/templates/incident.html"}

